import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum PricingMode {
  FIXED = 'FIXED',
  COMPONENTS = 'COMPONENTS'
}

export enum ContractStatus {
  DRAFT = 'Rascunho',
  AWAITING_SIGNATURE = 'Aguardando Assinatura',
  SIGNED = 'Assinado',
  COMPLETED = 'Concluído'
}

export interface Contract {
  id: string;
  number: string; // Ex: 1001S26
  product: 'SOJA' | 'MILHO' | 'TRIGO';
  crop: string; // Ex: 23/24
  sellerName: string;
  buyerName: string;
  totalBags: number; // Quantidade em sacas
  deliveredBags: number;

  // Financials
  currency: 'BRL' | 'USD';
  exchangeRate: number; // Câmbio

  pricingMode: PricingMode;
  isFixed: boolean; // Botão FIXAR

  // Pricing Components (Values per bag)
  basePrice: number; // Used for FIXED mode
  cbotComponent?: number;
  basisComponent?: number;
  costComponent?: number;
  finalPrice: number; // Calculated or Manual

  commissionPerBag: number;
  paymentDate: string;
  commissionDueDate: string; // paymentDate + 1

  status: ContractStatus;
  createdAt: string;
  signatureData?: {
    signedAt: string;
    ip: string;
    device: string;
  };
}

export interface Shipment {
  id: string;
  contractId: string;
  plate: string;
  ticketNumber: string;
  weightKg: number;
  bagsCount: number; // Calculated
  date: string;
}

export interface MarketData {
  usd: number;
  cbotCorn: number;
  cbotSoy: number;
}

