                </section>

                 {/* 5. Signatures (Existing) */}
                {editingContract && (
                    <section>
                         <h3 className="text-sm font-bold text-slate-900 uppercase tracking-wide mb-4">Assinatura Digital</h3>
                         <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 flex items-center justify-between">
