                            </div>
                            {editingContract.status === ContractStatus.SIGNED ? (
                                <div className="flex items-center gap-2 text-emerald-600 bg-white px-3 py-1 rounded shadow-sm border border-emerald-100">
                                    <CheckCircle className="w-5 h-5" />
