export const saveContract = (contract: Contract) => {
  const index = contracts.findIndex(c => c.id === contract.id);
  if (index >= 0) {
    contracts[index] = contract;
  } else {
    contracts.push(contract);
  }
  return contract;
};

export const getShipments = (contractId?: string) => {
  if (contractId) return shipments.filter(s => s.contractId === contractId);
  return shipments;
};

export const addShipment = (shipment: Shipment) => {
  shipments.push(shipment);
  const contract = contracts.find(c => c.id === shipment.contractId);
  if (contract) {
    contract.deliveredBags += shipment.bagsCount;
  }
  return shipment;
};

export const generateContractNumber = (product: string, crop: string): string => {
  // Logic: Sequential + Letter + Crop Year Suffix
  const letter = product === 'SOJA' ? 'S' : product === 'MILHO' ? 'M' : 'T';
  const cropSuffix = crop.split('/')[1] || crop.slice(-2) || '00';
  const existingCount = contracts.filter(c => c.number.includes(`${letter}${cropSuffix}`)).length;
  const seq = 1001 + existingCount;
  return `${seq}${letter}${cropSuffix}`;
};

import React, { useState, useEffect } from 'react';
import { Plus, Search, Filter, Download, FileSpreadsheet, Lock, Unlock, Edit2, Share2, CheckCircle, FileText, Calendar, MapPin, DollarSign, Truck, Calculator, Eye, Printer, X, Sprout } from 'lucide-react';
import { Contract, PricingMode, ContractStatus, MarketData, Producer, Buyer, FreightType } from '../types';
import { generateContractNumber, saveContract, getProducers, getBuyers } from '../services/mockService';

interface ContractsProps {
  contracts: Contract[];
  marketData: MarketData;
  onUpdate: () => void;
}

export const Contracts: React.FC<ContractsProps> = ({ contracts, marketData, onUpdate }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [viewingContract, setViewingContract] = useState<Contract | null>(null);
  const [editingContract, setEditingContract] = useState<Contract | null>(null);
  const [filter, setFilter] = useState('');

  // Mock Data Lists
  const [producersList, setProducersList] = useState<Producer[]>([]);
  const [buyersList, setBuyersList] = useState<Buyer[]>([]);

  // Custom Local State for Form Interaction
  const [isNewLocation, setIsNewLocation] = useState(false);
  const [availableLocations, setAvailableLocations] = useState<string[]>([]);

  // Form State
  const [formData, setFormData] = useState<Partial<Contract>>({
    pricingMode: PricingMode.FIXED,
    isFixed: false,
    currency: 'BRL',
    product: 'SOJA',
    crop: '23/24',
    freightType: 'FOB'
  });

  useEffect(() => {
    setProducersList(getProducers());
    setBuyersList(getBuyers());
  }, []);

  const handleEdit = (contract: Contract) => {
    setEditingContract(contract);
    setFormData({ ...contract });

    // Setup locations based on existing seller
    const seller = producersList.find(p => p.name === contract.sellerName);
    if(seller) {
        setAvailableLocations(seller.locations);
        if (!seller.locations.includes(contract.pickupLocation)) {
            setIsNewLocation(true);
        } else {
            setIsNewLocation(false);
        }
    } else {
        setAvailableLocations([]);
        setIsNewLocation(true);
    }

    setIsModalOpen(true);
  };

  const handleCreate = () => {
    const newNumber = generateContractNumber('SOJA', '23/24');
    setEditingContract(null);
    setFormData({
      number: newNumber,
      pricingMode: PricingMode.FIXED,
      product: 'SOJA',
      crop: '23/24',
      isFixed: false,
      currency: 'BRL',
      freightType: 'FOB',
      status: ContractStatus.DRAFT,
      commissionPerBag: 0.50,
      exchangeRate: marketData.usd
    });
    setAvailableLocations([]);
    setIsNewLocation(false);
    setIsModalOpen(true);
  };

  const handleSellerChange = (sellerName: string) => {
    const seller = producersList.find(p => p.name === sellerName);
    setFormData({...formData, sellerName});
    if (seller) {
        setAvailableLocations(seller.locations);
        // Default to first location if available
        if (seller.locations.length > 0) {
            setFormData(prev => ({...prev, sellerName, pickupLocation: seller.locations[0]}));
            setIsNewLocation(false);
        } else {
            setIsNewLocation(true);
            setFormData(prev => ({...prev, sellerName, pickupLocation: ''}));
        }
    } else {
        setAvailableLocations([]);
    }
  };

  const handleVolumeChange = (value: string, unit: 'BAGS' | 'TONS') => {
      const val = Number(value);
      if (unit === 'BAGS') {
          // Sacas -> Tons (1 sc = 60kg)
          const tons = (val * 60) / 1000;
          setFormData({ ...formData, totalBags: val, totalTons: parseFloat(tons.toFixed(3)) });
      } else {
          // Tons -> Sacas
          const bags = (val * 1000) / 60;
          // Usually we want integer bags for contracts, or keep decimals if precise
          setFormData({ ...formData, totalTons: val, totalBags: parseFloat(bags.toFixed(2)) });
      }
  };

  const handleSave = () => {
    if (!formData.sellerName || !formData.buyerName || !formData.totalBags || !formData.pickupLocation) {
        alert("Preencha os campos obrigatórios (Vendedor, Comprador, Volume, Local)");
        return;
    }

    if (!formData.shipmentStartDate || !formData.shipmentEndDate) {
        alert("Defina o período de embarque");
