    // Check Immediate (If start date is roughly created date, or just check if it's today logic? 
    // For simplicity, we check if day is not 1 or 16, usually implying immediate/specific date)
    const startDay = start.getUTCDate();
    if (startDay !== 1 && startDay !== 16) {
        setIsImmediate(true);
    } else {
        setIsImmediate(false);
        setStartFortnight(startDay <= 15 ? '1' : '2');
    }

    setStartMonth(start.getUTCMonth());
    setStartYear(start.getUTCFullYear());

    const endDay = end.getUTCDate();
    setEndFortnight(endDay <= 15 ? '1' : '2');
    setEndMonth(end.getUTCMonth());
    setEndYear(end.getUTCFullYear());

    // Setup locations based on existing seller
    const seller = producersList.find(p => p.name === contract.sellerName);
    if(seller) {
        setAvailableLocations(seller.locations);
        if (!seller.locations.includes(contract.pickupLocation)) {
            setIsNewLocation(true);
        } else {
            setIsNewLocation(false);
        }
    } else {
        setAvailableLocations([]);
        setIsNewLocation(true);
    }

    setIsModalOpen(true);
  };

