                            <div className="flex gap-4">
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input 
                                        type="radio" 
                                        name="pricingMode" 
                                        checked={formData.pricingMode === PricingMode.FIXED}
                                        onChange={() => setFormData({...formData, pricingMode: PricingMode.FIXED})}
                                        disabled={formData.isFixed}
                                        className="text-emerald-600 focus:ring-emerald-500"
                                    />
                                    <span className="text-sm font-medium text-slate-700">Preço Fixo</span>
                                </label>
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input 
                                        type="radio" 
                                        name="pricingMode" 
                                        checked={formData.pricingMode === PricingMode.COMPONENTS}
                                        onChange={() => setFormData({...formData, pricingMode: PricingMode.COMPONENTS})}
                                        disabled={formData.isFixed}
                                        className="text-emerald-600 focus:ring-emerald-500"
                                    />
                                    <span className="text-sm font-medium text-slate-700">Componentes</span>
                                </label>
                            </div>

                            {/* Currency Selector */}
                            <div className="flex gap-4 ml-auto border-l border-slate-300 pl-6">
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input 
                                        type="radio" 
                                        name="currency" 
                                        checked={formData.currency === 'BRL'}
                                        onChange={() => setFormData({...formData, currency: 'BRL'})}
                                        className="text-emerald-600 focus:ring-emerald-500"
                                    />
                                    <span className="text-sm font-medium text-slate-700">BRL (R$)</span>
                                </label>
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input 
                                        type="radio" 
                                        name="currency" 
                                        checked={formData.currency === 'USD'}
                                        onChange={() => setFormData({...formData, currency: 'USD'})}
                                        className="text-emerald-600 focus:ring-emerald-500"
                                    />
                                    <span className="text-sm font-medium text-slate-700">USD ($)</span>
                                </label>
                            </div>
                        </div>

                        {/* Fields */}
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                            {formData.pricingMode === PricingMode.COMPONENTS ? (
                                <>
                                    <div>
                                        <label className="block text-xs font-semibold text-slate-500 mb-1">CBOT</label>
                                        <input 
                                            type="number" 
                                            className="w-full rounded border border-slate-300 p-2 text-sm"
                                            disabled={formData.isFixed}
                                            value={formData.cbotComponent || ''}
                                            onChange={(e) => setFormData({...formData, cbotComponent: Number(e.target.value)})}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-semibold text-slate-500 mb-1">Basis</label>
                                        <input 
                                            type="number" 
                                            className="w-full rounded border border-slate-300 p-2 text-sm"
                                            disabled={formData.isFixed}
                                            value={formData.basisComponent || ''}
                                            onChange={(e) => setFormData({...formData, basisComponent: Number(e.target.value)})}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-semibold text-slate-500 mb-1">Custo/Prêmio</label>
                                        <input 
                                            type="number" 
                                            className="w-full rounded border border-slate-300 p-2 text-sm"
                                            disabled={formData.isFixed}
                                            value={formData.costComponent || ''}
                                            onChange={(e) => setFormData({...formData, costComponent: Number(e.target.value)})}
                                        />
                                    </div>
                                </>
                            ) : (
                                <div className="md:col-span-3">
                                     <label className="block text-xs font-semibold text-slate-500 mb-1">Preço Fixo / Saca ({formData.currency})</label>
                                        <input 
                                            type="number" 
                                            className="w-full rounded border border-slate-300 p-2 text-sm"
                                            disabled={formData.isFixed}
                                            value={formData.basePrice || ''}
                                            onChange={(e) => setFormData({...formData, basePrice: Number(e.target.value)})}
                                        />
                                </div>
                            )}

                            {/* Total Result */}
                            <div className={`p-3 rounded-lg border ${formData.isFixed ? 'bg-emerald-100 border-emerald-200' : 'bg-slate-200 border-slate-300'}`}>
                                <p className="text-xs font-bold text-slate-500 uppercase mb-1">
                                    {formData.isFixed ? 'Fechado' : 'Previsto'}
                                </p>
                                <p className={`text-xl font-bold ${formData.isFixed ? 'text-emerald-800' : 'text-slate-600'}`}>
                                    {formData.currency === 'USD' ? '$' : 'R$'} {calculatedPrice.toFixed(2)}
                                </p>
                            </div>
                        </div>

                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Data Pagamento Produto</label>
                                <input 
                                    type="date" 
                                    className="w-full rounded-lg border border-slate-300 p-2.5"
                                    value={formData.paymentDate || ''}
                                    onChange={(e) => setFormData({...formData, paymentDate: e.target.value})}
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Taxa de Câmbio (Ref)</label>
                                <input 
                                    type="number" 
                                    className="w-full rounded-lg border border-slate-300 p-2.5"
                                    value={formData.exchangeRate || ''}
                                    onChange={(e) => setFormData({...formData, exchangeRate: Number(e.target.value)})}
                                />
                            </div>
                         </div>
                    </div>
                </section>

                {/* 4. Observations */}
                <section>
                    <label className="block text-sm font-bold text-slate-900 uppercase tracking-wide mb-2">Observações do Contrato</label>
                    <textarea 
                        className="w-full rounded-lg border border-slate-300 p-3 h-24 text-sm"
                        placeholder="Insira detalhes adicionais, condições especiais de pagamento ou logística..."
                        value={formData.observation || ''}
                        onChange={(e) => setFormData({...formData, observation: e.target.value})}
                    />
                </section>

                 {/* 5. Signatures (Existing) */}
                {editingContract && (
                    <section>
                         <h3 className="text-sm font-bold text-slate-900 uppercase tracking-wide mb-4">Assinatura Digital</h3>
                         <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 flex items-center justify-between">
                            <div>
                                <p className="font-medium text-slate-800">Link para Assinatura do Vendedor</p>
                                <p className="text-sm text-slate-500">Gera um link único mobile-friendly</p>
                            </div>
                            {editingContract.status === ContractStatus.SIGNED ? (
                                <div className="flex items-center gap-2 text-emerald-600 bg-white px-3 py-1 rounded shadow-sm border border-emerald-100">
                                    <CheckCircle className="w-5 h-5" />
                                    <div className="text-xs">
                                        <p className="font-bold">Assinado em {new Date(editingContract.signatureData!.signedAt).toLocaleDateString()}</p>
                                        <p>IP: {editingContract.signatureData!.ip}</p>
                                    </div>
                                </div>
                            ) : (
                                <button className="flex items-center px-3 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 text-sm">
                                    <Share2 className="w-4 h-4 mr-2" />
                                    Enviar Link
                                </button>
                            )}
                         </div>
                    </section>
                )}

            </div>

            <div className="p-6 border-t border-slate-100 flex justify-end gap-3 bg-slate-50 rounded-b-xl sticky bottom-0">
                <button onClick={() => setIsModalOpen(false)} className="px-5 py-2 text-slate-600 hover:bg-slate-200 rounded-lg">Cancelar</button>
                <button onClick={handleSave} className="px-5 py-2 bg-emerald-600 text-white font-medium rounded-lg hover:bg-emerald-700 shadow-sm">
                    Salvar Contrato
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Search, Filter, Download, FileSpreadsheet, Lock, Unlock, Edit2, Share2, CheckCircle, FileText, Calendar, MapPin, DollarSign, Truck, Calculator, Eye, Printer, X, Sprout, FileBarChart, Settings2 } from 'lucide-react';
import { Contract, PricingMode, ContractStatus, MarketData, Producer, Buyer, FreightType } from '../types';
import { generateContractNumber, saveContract, getProducers, getBuyers } from '../services/mockService';

interface ContractsProps {
  contracts: Contract[];
  marketData: MarketData;
  onUpdate: () => void;
}

const MONTHS = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
];

const YEARS = [2024, 2025, 2026, 2027, 2028];

export const Contracts: React.FC<ContractsProps> = ({ contracts, marketData, onUpdate }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Report State
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [reportColumns, setReportColumns] = useState({
      date: true,
      contract: true,
      crop: true,
      seller: true,
      buyer: true,
      volume: true,
      price: true,
      status: true,
      freight: false
  });

  // Report Specific Filters
  const [reportFilters, setReportFilters] = useState({
      product: '',
      crop: '',
      seller: '',
      buyer: '',
      status: '',
      freight: '',
      currency: ''
  });

  const [viewingContract, setViewingContract] = useState<Contract | null>(null);
  const [editingContract, setEditingContract] = useState<Contract | null>(null);
  const [filter, setFilter] = useState('');

  // Mock Data Lists
  const [producersList, setProducersList] = useState<Producer[]>([]);
  const [buyersList, setBuyersList] = useState<Buyer[]>([]);

  // Custom Local State for Form Interaction
  const [isNewLocation, setIsNewLocation] = useState(false);
  const [availableLocations, setAvailableLocations] = useState<string[]>([]);

  // Shipment Period State (UI Only)
  const [isImmediate, setIsImmediate] = useState(false);
  const [startFortnight, setStartFortnight] = useState<'1' | '2'>('1');
  const [startMonth, setStartMonth] = useState(new Date().getMonth());
  const [startYear, setStartYear] = useState(new Date().getFullYear());

  const [endFortnight, setEndFortnight] = useState<'1' | '2'>('2');
  const [endMonth, setEndMonth] = useState(new Date().getMonth());
  const [endYear, setEndYear] = useState(new Date().getFullYear());

  // Form State
  const [formData, setFormData] = useState<Partial<Contract>>({
    pricingMode: PricingMode.FIXED,
    isFixed: false,
    currency: 'BRL',
    product: 'SOJA',
    crop: '23/24',
    freightType: 'FOB'
  });

  useEffect(() => {
    setProducersList(getProducers());
    setBuyersList(getBuyers());
  }, []);

  // Update underlying dates when UI selectors change
  useEffect(() => {
    if (!isModalOpen) return;

    let startDateStr = '';

    if (isImmediate) {
        startDateStr = new Date().toISOString().split('T')[0];
    } else {
        // 1st Fortnight = Day 1, 2nd Fortnight = Day 16
        const day = startFortnight === '1' ? 1 : 16;
        const d = new Date(startYear, startMonth, day);
        // Adjust for timezone offset to ensure string is correct
        d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
        startDateStr = d.toISOString().split('T')[0];
    }

    // End Date Logic
    // 1st Fortnight End = Day 15
    // 2nd Fortnight End = Last Day of Month
    let endDay = 15;
    if (endFortnight === '2') {
        endDay = new Date(endYear, endMonth + 1, 0).getDate();
    }
    const endDateObj = new Date(endYear, endMonth, endDay);
    endDateObj.setMinutes(endDateObj.getMinutes() - endDateObj.getTimezoneOffset());
    const endDateStr = endDateObj.toISOString().split('T')[0];

    setFormData(prev => ({
        ...prev,
        shipmentStartDate: startDateStr,
        shipmentEndDate: endDateStr
    }));

  }, [isImmediate, startFortnight, startMonth, startYear, endFortnight, endMonth, endYear, isModalOpen]);

  const handleEdit = (contract: Contract) => {
    setEditingContract(contract);
    setFormData({ ...contract });

    // Parse Dates to UI Selectors
    const start = new Date(contract.shipmentStartDate);
    const end = new Date(contract.shipmentEndDate);

    // Check Immediate (If start date is roughly created date, or just check if it's today logic? 
    // For simplicity, we check if day is not 1 or 16, usually implying immediate/specific date)
    const startDay = start.getUTCDate();
    if (startDay !== 1 && startDay !== 16) {
        setIsImmediate(true);
    } else {
        setIsImmediate(false);
        setStartFortnight(startDay <= 15 ? '1' : '2');
    }

    setStartMonth(start.getUTCMonth());
    setStartYear(start.getUTCFullYear());

    const endDay = end.getUTCDate();
    setEndFortnight(endDay <= 15 ? '1' : '2');
    setEndMonth(end.getUTCMonth());
    setEndYear(end.getUTCFullYear());

    // Setup locations based on existing seller
    const seller = producersList.find(p => p.name === contract.sellerName);
    if(seller) {
        setAvailableLocations(seller.locations);
        if (!seller.locations.includes(contract.pickupLocation)) {
            setIsNewLocation(true);
        } else {
            setIsNewLocation(false);
        }
    } else {
        setAvailableLocations([]);
        setIsNewLocation(true);
    }

    setIsModalOpen(true);
  };

  const handleCreate = () => {
    const newNumber = generateContractNumber('SOJA', '23/24');
    setEditingContract(null);
    setFormData({
      number: newNumber,
      pricingMode: PricingMode.FIXED,
      product: 'SOJA',
      crop: '23/24',
      isFixed: false,
      currency: 'BRL',
      freightType: 'FOB',
      status: ContractStatus.DRAFT,
      commissionPerBag: 0.50,
      exchangeRate: marketData.usd
    });

    // Default dates
    const today = new Date();
    setStartMonth(today.getMonth());
    setStartYear(today.getFullYear());
    setStartFortnight('1');
    setIsImmediate(false);

    setEndMonth(today.getMonth());
    setEndYear(today.getFullYear());
    setEndFortnight('2');

    setAvailableLocations([]);
    setIsNewLocation(false);
    setIsModalOpen(true);
  };

  const handleSellerChange = (sellerName: string) => {
    const seller = producersList.find(p => p.name === sellerName);
    setFormData({...formData, sellerName});
    if (seller) {
        setAvailableLocations(seller.locations);
        // Default to first location if available
        if (seller.locations.length > 0) {
            setFormData(prev => ({...prev, sellerName, pickupLocation: seller.locations[0]}));
            setIsNewLocation(false);
        } else {
            setIsNewLocation(true);
            setFormData(prev => ({...prev, sellerName, pickupLocation: ''}));
        }
    } else {
        setAvailableLocations([]);
    }
  };

  const handleVolumeChange = (value: string, unit: 'BAGS' | 'TONS') => {
      const val = Number(value);
      if (unit === 'BAGS') {
          // Sacas -> Tons (1 sc = 60kg)
          const tons = (val * 60) / 1000;
          setFormData({ ...formData, totalBags: val, totalTons: parseFloat(tons.toFixed(3)) });
      } else {
          // Tons -> Sacas
          const bags = (val * 1000) / 60;
          // Usually we want integer bags for contracts, or keep decimals if precise
          setFormData({ ...formData, totalTons: val, totalBags: parseFloat(bags.toFixed(2)) });
      }
  };

  const handleSave = () => {
    if (!formData.sellerName || !formData.buyerName || !formData.totalBags || !formData.pickupLocation) {
        alert("Preencha os campos obrigatórios (Vendedor, Comprador, Volume, Local)");
        return;
    }

    // Calc Payment Dates
    const paymentDate = formData.paymentDate || new Date().toISOString().split('T')[0];
    const commissionDate = new Date(paymentDate);
    commissionDate.setDate(commissionDate.getDate() + 1);

    // Audit Log logic simulation
    if (editingContract?.isFixed && formData.finalPrice !== editingContract.finalPrice) {
        if(!confirm("ALERTA DE AUDITORIA: Você está alterando o preço de um contrato já fixado. Confirma a alteração?")) {
            return;
        }
    }

    const finalContract: Contract = {
      id: editingContract?.id || Math.random().toString(36).substr(2, 9),
      number: formData.number!,
      product: formData.product as any,
      crop: formData.crop!,
      sellerName: formData.sellerName!,
      buyerName: formData.buyerName!,
      totalBags: Number(formData.totalBags),
      totalTons: Number(formData.totalTons || 0),
      deliveredBags: formData.deliveredBags || 0,
      freightType: formData.freightType as FreightType,
      pickupLocation: formData.pickupLocation!,
      shipmentStartDate: formData.shipmentStartDate!,
      shipmentEndDate: formData.shipmentEndDate!,
      observation: formData.observation || '',
      currency: formData.currency as any,
      exchangeRate: Number(formData.exchangeRate),
      pricingMode: formData.pricingMode as PricingMode,
      isFixed: formData.isFixed || false,
      basePrice: Number(formData.basePrice || 0),
      cbotComponent: Number(formData.cbotComponent || 0),
      basisComponent: Number(formData.basisComponent || 0),
      costComponent: Number(formData.costComponent || 0),
      finalPrice: Number(calculatePrice()), 
      commissionPerBag: Number(formData.commissionPerBag),
      paymentDate: paymentDate,
      commissionDueDate: commissionDate.toISOString().split('T')[0],
      status: formData.status as ContractStatus,
      createdAt: editingContract?.createdAt || new Date().toISOString()
    };

    saveContract(finalContract);
    onUpdate();
    setIsModalOpen(false);
  };

  // Pricing Logic
  const calculatePrice = () => {
    if (formData.pricingMode === PricingMode.FIXED) {
      return formData.basePrice || 0;
    } else {
      const cbot = Number(formData.cbotComponent || 0);
      const basis = Number(formData.basisComponent || 0);
      const cost = Number(formData.costComponent || 0);
      return (cbot + basis + cost);
    }
  };

  const calculatedPrice = calculatePrice();

  // Simulated Market Price (Scraping Mock)
  const marketPreview = formData.pricingMode === PricingMode.COMPONENTS 
    ? (marketData.cbotSoy / 100 * marketData.usd)
    : 140.00; 

  // Global Filter for Main Table
  const filteredContracts = contracts.filter(c => 
    c.number.toLowerCase().includes(filter.toLowerCase()) || 
    c.sellerName.toLowerCase().includes(filter.toLowerCase())
  );

  // --- REPORT LOGIC & HELPERS ---

  // Get unique values for dropdowns
  const uniqueCrops = useMemo(() => Array.from(new Set(contracts.map(c => c.crop))).sort(), [contracts]);
  const uniqueProducts = useMemo(() => Array.from(new Set(contracts.map(c => c.product))).sort(), [contracts]);
  const uniqueSellers = useMemo(() => Array.from(new Set(contracts.map(c => c.sellerName))).sort(), [contracts]);
  const uniqueBuyers = useMemo(() => Array.from(new Set(contracts.map(c => c.buyerName))).sort(), [contracts]);
  const uniqueStatus = useMemo(() => Array.from(new Set(contracts.map(c => c.status))).sort(), [contracts]);

  // Apply Report specific filters AND Global filter
  const reportData = useMemo(() => {
      return filteredContracts.filter(c => {
          if (reportFilters.crop && c.crop !== reportFilters.crop) return false;
          if (reportFilters.product && c.product !== reportFilters.product) return false;
          if (reportFilters.seller && c.sellerName !== reportFilters.seller) return false;
          if (reportFilters.buyer && c.buyerName !== reportFilters.buyer) return false;
          if (reportFilters.status && c.status !== reportFilters.status) return false;
          if (reportFilters.freight && c.freightType !== reportFilters.freight) return false;
          if (reportFilters.currency && c.currency !== reportFilters.currency) return false;
          return true;
      });
  }, [filteredContracts, reportFilters]);

  const getReportTitle = () => {
      const parts = ["RELATÓRIO DE CONTRATOS"];

      // Dynamic Title construction based on filters
      if (reportFilters.crop) parts.push(`SAFRA ${reportFilters.crop}`);
      if (reportFilters.product) parts.push(`PRODUTO: ${reportFilters.product}`);
      if (reportFilters.seller) parts.push(`VENDEDOR: ${reportFilters.seller}`);

      return parts.join(" - ");
  };

  const toggleReportColumn = (col: keyof typeof reportColumns) => {
      setReportColumns(prev => ({...prev, [col]: !prev[col]}));
  };

  // Helper to find full details
  const getFullSeller = (name: string) => producersList.find(p => p.name === name);
  const getFullBuyer = (name: string) => buyersList.find(b => b.name === name);

  // --- Date Formatting Helpers ---
  const formatFortnightDate = (dateStr: string, type: 'START' | 'END'): string => {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    const day = date.getUTCDate();
    const month = MONTHS[date.getUTCMonth()];
    const year = date.getUTCFullYear();
    const shortYear = year.toString().slice(-2);

    if (type === 'START') {
        if (day !== 1 && day !== 16) return "Imediato";
        const quin = day === 1 ? '1ª' : '2ª';
        return `${quin} Quinzena ${month}/${shortYear}`;
    } else {
        const quin = day <= 15 ? '1ª' : '2ª';
        return `${quin} Quinzena ${month}/${shortYear}`;
    }
  };

  const getPeriodDisplay = (start: string, end: string) => {
    const startTxt = formatFortnightDate(start, 'START');
    const endTxt = formatFortnightDate(end, 'END');

    if (startTxt === 'Imediato') return `Imediato até ${endTxt}`;
    return `${startTxt} a ${endTxt}`;
  };

  return (
    <div className="space-y-6">
      {/* Styles for Printing */}
      <style>{`
        @media print {
          body * {
            visibility: hidden;
          }
          /* Ensure we print the specific ID that is currently open */
          #printable-area, #printable-area *, 
          #printable-report, #printable-report * {
            visibility: visible;
          }

          /* Contract Modal View */
          #printable-area {
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
            background: white;
            padding: 0;
            margin: 0;
          }

          /* Report Modal View */
          #printable-report {
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
            background: white;
            padding: 0;
            margin: 0;
          }

          @page {
             size: A4;
             margin: 10mm;
          }
          .no-print {
            display: none !important;
          }
        }
      `}</style>

      {/* Action Bar */}
      <div className="flex flex-col sm:flex-row justify-between gap-4 no-print">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Buscar contratos..." 
            className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-emerald-500 outline-none"
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
          />
        </div>
        <div className="flex gap-2">
           <button onClick={() => setIsReportModalOpen(true)} className="flex items-center px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 shadow-sm transition-colors border border-slate-700">
            <FileBarChart className="w-5 h-5 mr-2" />
            Relatório PDF
          </button>
           <button className="flex items-center px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50">
            <FileSpreadsheet className="w-5 h-5 mr-2" />
            Importar CSV
          </button>
          <button className="flex items-center px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50">
            <Download className="w-5 h-5 mr-2" />
            Exportar
          </button>
          <button onClick={handleCreate} className="flex items-center px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 shadow-sm transition-colors">
            <Plus className="w-5 h-5 mr-2" />
