                                </button>
                            )}
                         </div>
                    </section>
                )}

            </div>

            <div className="p-6 border-t border-slate-100 flex justify-end gap-3 bg-slate-50 rounded-b-xl sticky bottom-0">
                <button onClick={() => setIsModalOpen(false)} className="px-5 py-2 text-slate-600 hover:bg-slate-200 rounded-lg">Cancelar</button>
                <button onClick={handleSave} className="px-5 py-2 bg-emerald-600 text-white font-medium rounded-lg hover:bg-emerald-700 shadow-sm">
                    Salvar Contrato
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export enum PricingMode {
  FIXED = 'FIXED',
  COMPONENTS = 'COMPONENTS'
}

export enum ContractStatus {
  DRAFT = 'Rascunho',
  AWAITING_SIGNATURE = 'Aguardando Assinatura',
  SIGNED = 'Assinado',
  COMPLETED = 'Concluído'
}

export type FreightType = 'CIF' | 'FOB';

export interface Contract {
  id: string;
  number: string; // Ex: 1001S26
  product: 'SOJA' | 'MILHO' | 'TRIGO';
  crop: string; // Ex: 23/24

  // Parties
  sellerName: string;
  buyerName: string;

  // Logistics & Terms
  totalBags: number; // Quantidade em sacas (60kg)
  totalTons: number; // Quantidade em toneladas
  deliveredBags: number;
  freightType: FreightType;
  pickupLocation: string; // Local de Embarque
  shipmentStartDate: string;
  shipmentEndDate: string;
  observation?: string;

  // Financials
  currency: 'BRL' | 'USD';
  exchangeRate: number; // Câmbio

  pricingMode: PricingMode;
  isFixed: boolean; // Botão FIXAR

  // Pricing Components (Values per bag)
  basePrice: number; // Used for FIXED mode
  cbotComponent?: number;
  basisComponent?: number;
  costComponent?: number;
  finalPrice: number; // Calculated or Manual

  commissionPerBag: number;
  paymentDate: string;
  commissionDueDate: string; // paymentDate + 1

  status: ContractStatus;
  createdAt: string;
  signatureData?: {
    signedAt: string;
    ip: string;
    device: string;
  };
}

export interface Shipment {
  id: string;
  contractId: string;
  plate: string;
  ticketNumber: string;
  weightKg: number;
  bagsCount: number; // Calculated
  date: string;
}

export interface MarketData {
  usd: number;
  cbotCorn: number;
  cbotSoy: number;
}

export interface BankAccount {
    bankName: string;
    agency: string;
    account: string;
    holder?: string; // Optional redundancy
    holderDoc?: string; // Optional redundancy
}

export interface Farm {
    id: string;
    name: string; // FAZENDA
    address: string; // ENDEREÇO FAZENDA
}

export interface Producer {
    id: string;
    name: string; // PRODUTOR
    doc: string; // CPF/CNPJ
    stateInsc: string; // I.E. VENDEDOR
    email?: string;
    region: string; // REGIÃO
    farms: Farm[]; // Lista de fazendas
    bankDetails: BankAccount;
    funruralType: 'FOLHA' | 'COMERCIALIZACAO'; // TIPO DE FUNRURAL
}

export interface Buyer {
    id: string;
    name: string; // COMPRADOR
    doc: string; // CNPJ
    stateInsc: string; // I.E.
    address: string; // ENDEREÇO
    type: 'TRADING' | 'MERCADO_INTERNO'; // TIPO
}

