                        </div>
                        <div className="md:col-span-2">
                            <label className="block text-sm font-medium text-slate-700 mb-1">Comprador (Trading/Fábrica)</label>
                             <select 
                                className="w-full rounded-lg border border-slate-300 p-2.5 bg-white"
