                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Toneladas</label>
                                <div className="relative">
                                     <input 
                                        type="number" 
                                        className="w-full rounded border border-slate-300 p-1.5 text-sm"
                                        placeholder="0.00"
