export const addShipment = async (shipment: Shipment) => {
    const dbShipment = {
        contract_id: shipment.contractId,
        plate: shipment.plate,
        ticket_number: shipment.ticketNumber,
        weight_kg: shipment.weightKg,
        bags_count: shipment.bagsCount,
        date: shipment.date
    };

    await supabase.from('shipments').insert(dbShipment);

    // Trigger update on contract delivered amount
    // In a real app, a Database Trigger is better. Here we do it via code.
    const { data: contract } = await supabase.from('contracts').select('delivered_bags').eq('id', shipment.contractId).single();
    if (contract) {
        const newTotal = (Number(contract.delivered_bags) || 0) + shipment.bagsCount;
        await supabase.from('contracts').update({ delivered_bags: newTotal }).eq('id', shipment.contractId);
    }
};

export const generateContractNumber = async (product: string, crop: string): Promise<string> => {
  const letter = product === 'SOJA' ? 'S' : product === 'MILHO' ? 'M' : 'T';
  const cleanCrop = crop.trim();
  let yearSuffix = '00';

  if (cleanCrop.includes('/')) {
    yearSuffix = cleanCrop.split('/')[1]; 
  } else if (cleanCrop.length >= 2) {
    yearSuffix = cleanCrop.slice(-2); 
  }

  // Count existing contracts for this product/crop to generate sequence
  // Note: This is prone to race conditions in high volume, but ok for basic ERP
  const { count } = await supabase
    .from('contracts')
    .select('*', { count: 'exact', head: true })
    .eq('product', product)
    .eq('crop', crop);

  const seq = 1001 + (count || 0);

  return `${seq}${letter}${yearSuffix}`;
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './pages/Dashboard';
import { Contracts } from './pages/Contracts';
import { Logistics } from './pages/Logistics';
import { Registries } from './pages/Registries';
import { getContracts, getMarketData, getShipments } from './services/mockService';
import { Contract, Shipment, MarketData } from './types';

export default function App() {
  const [activePage, setActivePage] = useState('dashboard');

  const [contracts, setContracts] = useState<Contract[]>([]);
  const [shipments, setShipments] = useState<Shipment[]>([]);
  const [marketData, setMarketData] = useState<MarketData>({ usd: 0, cbotSoy: 0, cbotCorn: 0 });
  const [loading, setLoading] = useState(true);

  const refreshData = async () => {
    setLoading(true);
    try {
      const [contractsData, shipmentsData] = await Promise.all([
        getContracts(),
        getShipments()
      ]);
      setContracts(contractsData);
      setShipments(shipmentsData);
      setMarketData(getMarketData()); // Still sync mock for now
    } catch (error) {
      console.error("Failed to load data", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refreshData();
  }, []);

  const renderContent = () => {
    if (loading) {
      return (
        <div className="h-full flex flex-col items-center justify-center text-emerald-800">
           <div className="w-12 h-12 border-4 border-emerald-200 border-t-emerald-600 rounded-full animate-spin mb-4"></div>
           <p className="animate-pulse">Carregando dados do sistema...</p>
        </div>
      );
    }

    switch (activePage) {
      case 'dashboard':
        return <Dashboard marketData={marketData} contracts={contracts} />;
      case 'contracts':
        return <Contracts contracts={contracts} marketData={marketData} onUpdate={refreshData} />;
      case 'logistics':
        return <Logistics contracts={contracts} shipments={shipments} onUpdate={refreshData} />;
      case 'registries':
        return <Registries />;
      default:
        return <div className="p-10 text-center text-slate-500">Módulo em desenvolvimento...</div>;
    }
  };

  return (
    <Layout activePage={activePage} onNavigate={setActivePage}>
      {renderContent()}
    </Layout>
  );
}

