        >
            <Plus className="w-5 h-5" />
            Lançar Ticket de Pesagem
        </button>

        {/* Add Ticket Form */}
        {showAddTicket && (
            <div className="bg-white p-6 rounded-xl shadow-lg border border-emerald-100 animate-in fade-in slide-in-from-top-4">
