                            <input 
                                type="number" 
                                className="w-full border border-slate-300 rounded-lg p-2 mt-1 pl-8"
                                placeholder="0"
                                value={ticketData.weightKg || ''}
                                onChange={(e) => setTicketData({...ticketData, weightKg: Number(e.target.value)})}
                            />
                            <Scale className="w-4 h-4 text-slate-400 absolute left-2.5 top-4" />
                        </div>
                    </div>
                </div>
                <div className="mt-4 flex justify-end gap-2">
                    <button onClick={() => setShowAddTicket(false)} className="px-4 py-2 text-slate-500">Cancelar</button>
                    <button onClick={handleAddTicket} disabled={isSubmitting} className="px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 flex items-center">
                        {isSubmitting && <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin mr-2"></div>}
                        Confirmar Lançamento
                    </button>
                </div>
            </div>
        )}

        {/* History List */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <h4 className="font-bold text-slate-800 p-4 border-b border-slate-100 bg-slate-50">Histórico de Embarques</h4>
            {contractShipments.length === 0 ? (
                <div className="p-8 text-center text-slate-400">Nenhum embarque registrado.</div>
            ) : (
                <table className="w-full text-sm text-left">
                    <thead className="bg-white text-slate-500 border-b border-slate-100">
                        <tr>
                            <th className="px-6 py-3 font-medium">Data</th>
                            <th className="px-6 py-3 font-medium">Placa</th>
                            <th className="px-6 py-3 font-medium">Ticket</th>
                            <th className="px-6 py-3 font-medium text-right">Peso (Kg)</th>
                            <th className="px-6 py-3 font-medium text-right">Sacas</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                        {contractShipments.map(s => (
                            <tr key={s.id}>
                                <td className="px-6 py-3 text-slate-600">{new Date(s.date).toLocaleDateString()}</td>
                                <td className="px-6 py-3 font-mono font-bold text-slate-700">{s.plate}</td>
                                <td className="px-6 py-3 text-slate-600">{s.ticketNumber}</td>
                                <td className="px-6 py-3 text-right">{s.weightKg.toLocaleString()}</td>
                                <td className="px-6 py-3 text-right font-bold text-emerald-700">{s.bagsCount}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}
        </div>

      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Search, Edit2, Trash2, Tractor, Building2, MapPin, X, Save, Eye, Wallet, FileText } from 'lucide-react';
import { Producer, Buyer, Farm } from '../types';
import { getProducers, getBuyers, saveProducer, saveBuyer, deleteProducer, deleteBuyer } from '../services/mockService';

export const Registries: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'producers' | 'buyers'>('producers');
  const [searchTerm, setSearchTerm] = useState('');

  // Data State
  const [producers, setProducers] = useState<Producer[]>([]);
  const [buyers, setBuyers] = useState<Buyer[]>([]);
  const [loading, setLoading] = useState(false);

  // Modal State
  const [isProducerModalOpen, setIsProducerModalOpen] = useState(false);
  const [isBuyerModalOpen, setIsBuyerModalOpen] = useState(false);

  // View Modal State
  const [viewingProducer, setViewingProducer] = useState<Producer | null>(null);
  const [viewingBuyer, setViewingBuyer] = useState<Buyer | null>(null);

  // Form State
  const [producerForm, setProducerForm] = useState<Partial<Producer>>({
      farms: [],
      bankDetails: { bankName: '', agency: '', account: '' },
      funruralType: 'COMERCIALIZACAO'
  });

  const [buyerForm, setBuyerForm] = useState<Partial<Buyer>>({
      type: 'TRADING'
  });

  // Temporary Farm State for the Form
  const [tempFarm, setTempFarm] = useState<Partial<Farm>>({ name: '', address: '' });

  const refreshData = async () => {
    setLoading(true);
    const [p, b] = await Promise.all([getProducers(), getBuyers()]);
    setProducers(p);
    setBuyers(b);
    setLoading(false);
  };

  useEffect(() => {
    refreshData();
  }, []);

  // --- Handlers for PRODUCER ---

  const handleEditProducer = (p: Producer) => {
    setProducerForm(JSON.parse(JSON.stringify(p))); // Deep copy
    setIsProducerModalOpen(true);
  };

  const handleNewProducer = () => {
    setProducerForm({
        id: Math.random().toString(36).substr(2, 9), // Temp ID for new
        farms: [],
        bankDetails: { bankName: '', agency: '', account: '' },
        funruralType: 'COMERCIALIZACAO'
    });
    setIsProducerModalOpen(true);
  };

  const handleSaveProducer = async () => {
    if (!producerForm.name || !producerForm.doc) {
        alert("Preencha Nome e CPF/CNPJ");
        return;
    }
    setLoading(true);
    await saveProducer(producerForm as Producer);
    await refreshData();
    setIsProducerModalOpen(false);
  };

  const handleDeleteProducer = async (id: string) => {
    if(confirm('Excluir este produtor?')) {
        setLoading(true);
        await deleteProducer(id);
        await refreshData();
    }
  };

  const addFarm = () => {
      if(!tempFarm.name) return;
      const newFarm: Farm = {
          id: Math.random().toString(36).substr(2, 9),
          name: tempFarm.name,
          address: tempFarm.address || ''
      };
      setProducerForm(prev => ({
          ...prev,
          farms: [...(prev.farms || []), newFarm]
      }));
      setTempFarm({ name: '', address: '' });
  };

  const removeFarm = (id: string) => {
      setProducerForm(prev => ({
          ...prev,
          farms: prev.farms?.filter(f => f.id !== id)
      }));
  };

  // --- Handlers for BUYER ---

  const handleEditBuyer = (b: Buyer) => {
    setBuyerForm(JSON.parse(JSON.stringify(b)));
    setIsBuyerModalOpen(true);
  };

  const handleNewBuyer = () => {
    setBuyerForm({
        id: Math.random().toString(36).substr(2, 9),
        type: 'TRADING'
    });
    setIsBuyerModalOpen(true);
  };

  const handleSaveBuyer = async () => {
     if (!buyerForm.name || !buyerForm.doc) {
        alert("Preencha Nome e CNPJ");
        return;
    }
    setLoading(true);
    await saveBuyer(buyerForm as Buyer);
    await refreshData();
    setIsBuyerModalOpen(false);
  };

  const handleDeleteBuyer = async (id: string) => {
