const CSV_TEMPLATES = {
    producers: `name,doc,state_insc,region,email,funrural_type,bank_name,agency,account\nJoão Silva,111.222.333-44,12345678,Pedro Afonso,joao@email.com,COMERCIALIZACAO,Banco do Brasil,1234-5,99999-X`,
