                             <label className={`flex items-center justify-center gap-2 w-full py-2 bg-amber-600 text-white text-xs font-bold uppercase rounded cursor-pointer hover:bg-amber-700 ${loading ? 'opacity-50 pointer-events-none' : ''}`}>
