// Specialized Producer Insert (Handles Bank Details JSON)
export const bulkInsertProducers = async (data: any[]) => {
    const formattedData = data.map(row => {
        // Normalização do Tipo de Funrural
        let fType = row.funrural_type ? row.funrural_type.toString().trim().toUpperCase() : null;

        if (fType === 'FOLHA' || fType === 'EM FOLHA' || fType === 'FOLHA.') fType = 'FOLHA';
        else if (fType === 'PJ_ISENTO' || fType === 'PJ (ISENTO)' || fType === 'PJ' || fType === 'ISENTO') fType = 'PJ_ISENTO';
        else if (fType === 'COMERCIALIZACAO' || fType === 'COMERCIALIZAÇÃO') fType = 'COMERCIALIZACAO';
        else fType = null; // Se não reconhecer (ex: lixo de coluna deslocada), envia NULL para não travar o banco

        return {
            name: row.name,
            doc: row.doc,
            state_insc: row.state_insc,
            email: row.email,
            region: row.region,
            funrural_type: fType,
            // Compress bank columns into single JSONB object
            bank_details: {
                bankName: row.bank_name || '',
                agency: row.agency || '',
                account: row.account || '',
                holder: row.holder || row.name, // Default to producer name if empty
                holderDoc: row.holder_doc || row.doc // Default to producer doc if empty
            }
        };
    });

    const { error } = await supabase.from('producers').insert(formattedData);
    if (error) throw error;
};

// Specialized Farm Insert (Links to Producer by Doc)
export const bulkInsertFarms = async (csvData: any[]) => {
    if (csvData.length === 0) return;

    // 1. Extract all producer documents from CSV
    const documents = [...new Set(csvData.map(row => row.producer_doc).filter(Boolean))];

    // 2. Fetch Producer IDs matching these documents
    const { data: producers, error } = await supabase
        .from('producers')
        .select('id, doc')
        .in('doc', documents);

    if (error) throw new Error('Erro ao buscar produtores: ' + error.message);
    if (!producers) return;

    // 3. Create a map: Document -> UUID
    const docMap = new Map();
    producers.forEach(p => docMap.set(p.doc, p.id));

    // 4. Prepare Farms for Insert
    const farmsToInsert: any[] = [];
    const errors: string[] = [];

    csvData.forEach(row => {
        const producerId = docMap.get(row.producer_doc);
        if (producerId) {
            farmsToInsert.push({
                producer_id: producerId,
                name: row.name,
                address: row.address
            });
        } else {
            errors.push(`Produtor com CPF/CNPJ ${row.producer_doc} não encontrado.`);
        }
    });

    // 5. Insert
    if (farmsToInsert.length > 0) {
        const { error: insertError } = await supabase.from('farms').insert(farmsToInsert);
        if (insertError) throw insertError;
    }

    if (errors.length > 0) {
        console.warn("Algumas fazendas não foram importadas:", errors);
        throw new Error(`Importação parcial. ${farmsToInsert.length} salvas. ${errors.length} falharam (Produtor não encontrado).`);
    }
};

