                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">

                    {/* PRODUCERS CARD */}
                    <div className="border border-slate-200 rounded-xl p-5 hover:border-emerald-200 transition-colors">
