        let inQuote = false;

        for (let i = 0; i < line.length; i++) {
            const char = line[i];

            if (char === '"') {
                if (inQuote && line[i + 1] === '"') {
                    // Aspas duplas escapadas ("")
                    current += '"';
                    i++;
                } else {
                    // Alterna estado de citação
                    inQuote = !inQuote;
                }
            } else if (char === ',' && !inQuote) {
                // Fim do campo
                values.push(current.trim());
                current = '';
            } else {
                current += char;
            }
        }
        values.push(current.trim());
        return values;
    };

