    // Helper to normalize dates (YYYY/MM/DD -> YYYY-MM-DD)
    const normalizeDate = (val: any): any => {
        if (typeof val === 'string' && val.includes('/')) {
            // Check if it looks like a date
            if (val.match(/^\d{4}\/\d{2}\/\d{2}$/)) {
                return val.replace(/\//g, '-');
            }
        }
        return val;
