    // Parser CSV Robusto que suporta aspas (RFC 4180 básico)
    const parseCSVLine = (line: string): string[] => {
        const values: string[] = [];
        let current = '';
        let inQuote = false;

        for (let i = 0; i < line.length; i++) {
            const char = line[i];

            if (char === '"') {
                if (inQuote && line[i + 1] === '"') {
                    // Aspas duplas escapadas ("")
                    current += '"';
                    i++;
                } else {
                    // Alterna estado de citação
                    inQuote = !inQuote;
                }
            } else if (char === ',' && !inQuote) {
