                    header !== 'buyer_doc' && // Force String
                    header !== 'number' &&
                    header !== 'account' &&
                    header !== 'agency' &&
                    header !== 'state_insc' &&
                    header !== 'ticket_number' &&
                    !header.includes('date') &&
                    header !== 'currency'
                ) {
