                }

                setImportStatus({msg: `Falha: ${errorMsg}`, type: 'error'});
            } finally {
                setLoading(false);
            }
        };

        // CRITICAL FIX: Read with specific encoding to handle accents
        reader.readAsText(file, fileEncoding);
    };

