export const Settings: React.FC = () => {
    const [importStatus, setImportStatus] = useState<{msg: string, type: 'success' | 'error' | ''}>({msg: '', type: ''});
    const [loading, setLoading] = useState(false);
    const [fileEncoding, setFileEncoding] = useState<'UTF-8' | 'ISO-8859-1'>('ISO-8859-1');

    const handleDownloadTemplate = (type: keyof typeof CSV_TEMPLATES) => {
        const csvContent = "data:text/csv;charset=utf-8," + encodeURIComponent(CSV_TEMPLATES[type]);
        const link = document.createElement("a");
        link.setAttribute("href", csvContent);
        link.setAttribute("download", `modelo_importacao_${type}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    // Validador Inteligente de Datas
    const normalizeDate = (val: any): string | null => {
        if (!val) return null;
        let str = String(val).trim();

        // Remove aspas extras se houver, embora o parser já deva fazer isso
        str = str.replace(/^["']|["']$/g, '');

        // Formato ISO: YYYY-MM-DD ou YYYY/MM/DD
        if (str.match(/^\d{4}[\/\-]\d{2}[\/\-]\d{2}$/)) {
            return str.replace(/\//g, '-');
        }

        // Formato BR: DD/MM/YYYY
        if (str.match(/^\d{2}[\/\-]\d{2}[\/\-]\d{4}$/)) {
            const parts = str.replace(/\//g, '-').split('-');
            return `${parts[2]}-${parts[1]}-${parts[0]}`; // Converte para YYYY-MM-DD
        }

        // Formato BR Curto: DD/MM/YY (Ex: 02/06/23)
        if (str.match(/^\d{2}[\/\-]\d{2}[\/\-]\d{2}$/)) {
            const parts = str.replace(/\//g, '-').split('-');
            return `20${parts[2]}-${parts[1]}-${parts[0]}`; // Assume ano 20XX
        }

        // Se chegou aqui, é texto (ex: "72h após embarque") -> Retorna null para não quebrar o banco
        return null;
    };

    const parseCSVLine = (line: string): string[] => {
        const values: string[] = [];
        let current = '';
        let inQuote = false;

        for (let i = 0; i < line.length; i++) {
            const char = line[i];

            if (char === '"') {
                if (inQuote && line[i + 1] === '"') {
                    current += '"';
                    i++;
                } else {
                    inQuote = !inQuote;
                }
            } else if (char === ',' && !inQuote) {
                values.push(current.trim());
                current = '';
            } else {
                current += char;
            }
        }
        values.push(current.trim());
        return values;
    };

    const parseCSV = (text: string): any[] => {
        const rows = text.trim().split('\n');
        if (rows.length < 2) return [];

        const headers = parseCSVLine(rows[0]).map(h => h.trim());
        const data = [];

        for (let i = 1; i < rows.length; i++) {
            const row = rows[i].trim();
            if (!row) continue;

            const values = parseCSVLine(row);
            if (values.length < 2) continue;

            const obj: any = {};
            let observationNote = ''; // Buffer para guardar erros de data

            headers.forEach((header, index) => {
                let val: any = values[index];

                // Limpeza final de aspas
                if (typeof val === 'string' && val.startsWith('"') && val.endsWith('"')) {
                    val = val.slice(1, -1);
                }

                // Tratamento Especial para Datas
                if (header.includes('date')) {
                    const cleanDate = normalizeDate(val);
                    if (val && !cleanDate) {
                        // É texto em campo de data! Move para observação.
                        observationNote += ` [${header}: ${val}]`;
                        val = null; 
                    } else {
                        val = cleanDate;
                    }
                }

                // Conversão Numérica (se for número válido)
                if (val && !isNaN(Number(val)) && 
                    header !== 'doc' && 
                    header !== 'producer_doc' && 
                    header !== 'seller_doc' && 
                    header !== 'buyer_doc' && 
                    header !== 'number' &&
                    header !== 'account' &&
                    header !== 'agency' &&
                    header !== 'state_insc' &&
                    header !== 'ticket_number' &&
                    !header.includes('date') &&
                    header !== 'currency'
                ) {
                     val = Number(val);
                }

                obj[header] = val;
            });

            // Se houve datas inválidas (textos), salva na observação
            if (observationNote) {
                obj.observation = (obj.observation || '') + observationNote;
            }

            data.push(obj);
        }
        return data;
    };

    const handleImport = async (table: string, event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        setLoading(true);
        setImportStatus({msg: 'Lendo arquivo...', type: ''});

        const reader = new FileReader();

        reader.onload = async (e) => {
            try {
                const text = e.target?.result as string;
                const data = parseCSV(text);

                if (data.length === 0) throw new Error("Arquivo vazio ou formato inválido");

                if (table === 'farms') {
                    await bulkInsertFarms(data);
                } else if (table === 'producers') {
                    await bulkInsertProducers(data);
                } else {
                    await bulkInsert(table, data);
                }

                setImportStatus({msg: `Sucesso! ${data.length} registros importados/atualizados.`, type: 'success'});
                event.target.value = '';
            } catch (error: any) {
                console.error(error);
                let errorMsg = error.message || 'Erro desconhecido';

                if (errorMsg.includes('violates check constraint')) {
                     errorMsg = "Erro de validação: Um dos campos (provavelmente Funrural ou Tipo) contém um valor inválido.";
                } else if (errorMsg.includes('violates unique constraint')) {
                     errorMsg = "Erro de duplicidade: Verifique se os dados chave (Número Contrato ou CPF) estão corretos.";
                } else if (errorMsg.includes('invalid input syntax for type date')) {
                     errorMsg = "Erro de Formatação: O banco rejeitou uma data inválida. Verifique se o CSV tem textos em colunas de data que o sistema não conseguiu limpar.";
                }

                setImportStatus({msg: `Falha: ${errorMsg}`, type: 'error'});
            } finally {
                setLoading(false);
            }
        };

        reader.readAsText(file, fileEncoding);
    };

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-slate-100 rounded-lg">
                            <Database className="w-6 h-6 text-slate-700" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-slate-800">Gerenciamento de Dados</h2>
                            <p className="text-slate-500 text-sm">Importação e Exportação em lote via CSV</p>
                        </div>
                    </div>

                    <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-lg border border-slate-200">
                        <Settings2 className="w-4 h-4 text-slate-500" />
                        <label className="text-xs font-bold text-slate-600">Codificação:</label>
                        <select 
                            value={fileEncoding}
                            onChange={(e) => setFileEncoding(e.target.value as any)}
                            className="bg-white border border-slate-300 rounded text-xs py-1 px-2 outline-none focus:border-emerald-500"
                        >
                            <option value="ISO-8859-1">Excel / Windows (ISO-8859-1)</option>
                            <option value="UTF-8">Padrão Web (UTF-8)</option>
                        </select>
                    </div>
                </div>

                {importStatus.msg && (
                    <div className={`p-4 rounded-lg mb-6 flex items-center gap-2 ${importStatus.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                        {importStatus.type === 'success' ? <CheckCircle className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
                        {importStatus.msg}
                    </div>
