import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './pages/Dashboard';
import { Contracts } from './pages/Contracts';
import { Logistics } from './pages/Logistics';
import { Registries } from './pages/Registries';
import { Reports } from './pages/Reports'; // NEW IMPORT
import { Settings } from './pages/Settings';
import { getContracts, getMarketData, getShipments } from './services/mockService';
import { Contract, Shipment, MarketData } from './types';

export default function App() {
  const activePageStorage = sessionStorage.getItem('dms_active_page') || 'dashboard';
  const [activePage, setActivePage] = useState(activePageStorage);

  const [contracts, setContracts] = useState<Contract[]>([]);
  const [shipments, setShipments] = useState<Shipment[]>([]);
  const [marketData, setMarketData] = useState<MarketData>({ usd: 0, cbotSoy: 0, cbotCorn: 0 });
  const [loading, setLoading] = useState(true);

  const handleNavigate = (page: string) => {
      setActivePage(page);
      sessionStorage.setItem('dms_active_page', page);
  };

  const refreshData = async () => {
    setLoading(true);
    try {
      const [contractsData, shipmentsData] = await Promise.all([
        getContracts(),
        getShipments()
      ]);
      setContracts(contractsData);
      setShipments(shipmentsData);
      setMarketData(getMarketData()); // Still sync mock for now
    } catch (error) {
      console.error("Failed to load data", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refreshData();
  }, []);

  const renderContent = () => {
    if (loading) {
      return (
        <div className="h-full flex flex-col items-center justify-center text-emerald-800">
           <div className="w-12 h-12 border-4 border-emerald-200 border-t-emerald-600 rounded-full animate-spin mb-4"></div>
           <p className="animate-pulse">Carregando dados do sistema...</p>
        </div>
      );
    }

    switch (activePage) {
      case 'dashboard':
        return <Dashboard marketData={marketData} contracts={contracts} />;
      case 'contracts':
        return <Contracts contracts={contracts} marketData={marketData} onUpdate={refreshData} />;
      case 'reports':
        return <Reports contracts={contracts} />;
      case 'logistics':
        return <Logistics contracts={contracts} shipments={shipments} onUpdate={refreshData} />;
      case 'registries':
        return <Registries />;
      case 'settings':
        return <Settings />;
      default:
        return <div className="p-10 text-center text-slate-500">Módulo em desenvolvimento...</div>;
    }
  };

  return (
    <Layout activePage={activePage} onNavigate={handleNavigate}>
      {renderContent()}
    </Layout>
  );
}

import React, { useState, useMemo } from 'react';
import { 
    LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ComposedChart, Area 
} from 'recharts';
import { Calendar, TrendingUp, DollarSign, Wallet, ArrowUpRight, ArrowDownRight, Filter } from 'lucide-react';
import { Contract } from '../types';

interface ReportsProps {
    contracts: Contract[];
}

const MONTH_NAMES = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'];

export const Reports: React.FC<ReportsProps> = ({ contracts }) => {
    const [activeTab, setActiveTab] = useState<'VOLUME' | 'FINANCIAL'>('VOLUME');
    const [selectedProduct, setSelectedProduct] = useState<string>('SOJA');
    const [comparisonDate, setComparisonDate] = useState<string>(new Date().toISOString().split('T')[0]);

    // --- LOGIC 1: SAFRA PACING (EVOLUÇÃO COMPARATIVA) ---
    // Objetivo: Comparar dia 17/02 da Safra X com 17/02 da Safra Y
    const pacingData = useMemo(() => {
        // 1. Identificar Safras disponíveis
        const crops = Array.from(new Set(contracts.map(c => c.crop))).sort();

        // 2. Filtrar pelo produto selecionado
        const relevantContracts = contracts.filter(c => c.product === selectedProduct);

        // 3. Criar uma estrutura de dados baseada em "Dia do Ano" (MM-DD)
        // O Recharts precisa de um array de objetos: [{ date: '01-01', '23/24': 100, '24/25': 0 }, ...]

        const timelineData: Record<string, any> = {};

        // Inicializa estrutura
        relevantContracts.forEach(c => {
            const date = new Date(c.createdAt);
            // Normalizar para um "Ano Genérico" para sobrepor as linhas no gráfico
            // Usamos formato MM-DD para ordenação
            const month = String(date.getMonth() + 1).padStart(2, '0');
            const day = String(date.getDate()).padStart(2, '0');
            const key = `${month}-${day}`;

            if (!timelineData[key]) {
                timelineData[key] = { name: `${day}/${month}`, rawDate: key };
                crops.forEach(crop => timelineData[key][crop] = 0);
            }
        });

        // Preenche volume diário
        relevantContracts.forEach(c => {
            const date = new Date(c.createdAt);
            const month = String(date.getMonth() + 1).padStart(2, '0');
            const day = String(date.getDate()).padStart(2, '0');
            const key = `${month}-${day}`;

            if(timelineData[key]) {
                timelineData[key][c.crop] = (timelineData[key][c.crop] || 0) + c.totalBags;
            }
        });

        // Converte para array e ordena
        const sortedData = Object.values(timelineData).sort((a: any, b: any) => a.rawDate.localeCompare(b.rawDate));

        // Transforma em ACUMULADO (Cumulative Sum)
        const finalData = [];
        const runningTotals: Record<string, number> = {};
        crops.forEach(c => runningTotals[c] = 0);

        for (const dayData of sortedData) {
            const newRow: any = { name: dayData.name, rawDate: dayData.rawDate };

            crops.forEach(crop => {
                runningTotals[crop] += (dayData[crop] || 0);
                newRow[crop] = runningTotals[crop];
            });
            finalData.push(newRow);
        }

        return { chartData: finalData, crops };
    }, [contracts, selectedProduct]);

    // KPI de Pacing: Volume na data selecionada
    const pacingMetrics = useMemo(() => {
        // Pega o dia/mês da data selecionada
        const targetDate = new Date(comparisonDate);
        const targetKey = `${String(targetDate.getMonth() + 1).padStart(2, '0')}-${String(targetDate.getDate()).padStart(2, '0')}`;

        // Encontra o ponto no gráfico mais próximo (ou igual) a essa data
        // Como o gráfico é acumulativo, pegamos o último registro que seja <= targetKey
        const snapshot = pacingData.chartData.filter((d: any) => d.rawDate <= targetKey).pop();

        return snapshot || {};
    }, [pacingData, comparisonDate]);


    // --- LOGIC 2: FINANCIAL FORECAST (COMISSÕES) ---
    const financialData = useMemo(() => {
        const dataByMonth: Record<string, { month: string, revenue: number, volume: number }> = {};

        contracts.forEach(c => {
            // Usar data de pagamento ou data de vencimento da comissão
            const payDate = new Date(c.paymentDate);
            const key = `${payDate.getFullYear()}-${String(payDate.getMonth() + 1).padStart(2, '0')}`;
            const label = `${MONTH_NAMES[payDate.getMonth()]}/${payDate.getFullYear().toString().substr(2)}`;

            if (!dataByMonth[key]) {
                dataByMonth[key] = { month: label, revenue: 0, volume: 0 };
            }

            // Calculo da Comissão
            const commissionVal = c.totalBags * c.commissionPerBag;

            // Só soma se não for cancelado (status draft conta como previsão futura)
            dataByMonth[key].revenue += commissionVal;
            dataByMonth[key].volume += c.totalBags;
        });

        return Object.entries(dataByMonth)
            .sort((a, b) => a[0].localeCompare(b[0]))
            .map(([_, val]) => val);
    }, [contracts]);

    const totalRevenueForecast = financialData.reduce((acc, curr) => acc + curr.revenue, 0);

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800">Relatórios Gerenciais</h2>
                    <p className="text-slate-500 text-sm">Visão consolidada para Diretoria (CO)</p>
                </div>

                {/* TABS SWITCHER */}
                <div className="bg-slate-200 p-1 rounded-lg flex">
                    <button 
                        onClick={() => setActiveTab('VOLUME')}
                        className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'VOLUME' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-600 hover:text-emerald-700'}`}
                    >
                        <TrendingUp className="w-4 h-4" /> Evolução de Safra
                    </button>
                    <button 
                        onClick={() => setActiveTab('FINANCIAL')}
                        className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'FINANCIAL' ? 'bg-white text-blue-700 shadow-sm' : 'text-slate-600 hover:text-blue-700'}`}
                    >
                        <Wallet className="w-4 h-4" /> Fluxo Financeiro
                    </button>
                </div>
            </div>

            {/* --- ABA 1: VOLUME PACING --- */}
            {activeTab === 'VOLUME' && (
                <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {/* Controls */}
                    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-4 items-center mb-6">
                         <div className="flex items-center gap-2">
                            <Filter className="w-4 h-4 text-slate-500" />
                            <span className="text-sm font-bold text-slate-700">Produto:</span>
                            <select 
                                value={selectedProduct}
                                onChange={(e) => setSelectedProduct(e.target.value)}
                                className="border border-slate-300 rounded px-2 py-1 text-sm bg-slate-50 font-medium"
                            >
                                <option value="SOJA">Soja</option>
                                <option value="MILHO">Milho</option>
                                <option value="TRIGO">Trigo</option>
                            </select>
                        </div>
                        <div className="w-px h-6 bg-slate-200"></div>
                        <div className="flex items-center gap-2">
                            <Calendar className="w-4 h-4 text-slate-500" />
                            <span className="text-sm font-bold text-slate-700">Data de Corte (Análise):</span>
                            <input 
                                type="date" 
                                value={comparisonDate}
                                onChange={(e) => setComparisonDate(e.target.value)}
                                className="border border-slate-300 rounded px-2 py-1 text-sm bg-slate-50"
