export const saveContract = async (contract: Contract) => {
    const dbContract = {
        number: contract.number,
        product: contract.product,
        crop: contract.crop,
        seller_name: contract.sellerName,
        seller_doc: contract.sellerDoc,
        buyer_name: contract.buyerName,
        buyer_doc: contract.buyerDoc,
        total_bags: contract.totalBags,
        total_tons: contract.totalTons,
        delivered_bags: contract.deliveredBags,
        freight_type: contract.freightType,
        pickup_location: contract.pickupLocation,
        shipment_start_date: contract.shipmentStartDate,
        shipment_end_date: contract.shipmentEndDate,
        observation: contract.observation,
        currency: contract.currency,
        exchange_rate: contract.exchangeRate,
        pricing_mode: contract.pricingMode,
        is_fixed: contract.isFixed,
        base_price: contract.basePrice,
        cbot_component: contract.cbotComponent,
        basis_component: contract.basisComponent,
        cost_component: contract.costComponent,
        final_price: contract.finalPrice,
        commission_per_bag: contract.commissionPerBag,
        payment_date: contract.paymentDate,
        commission_due_date: contract.commissionDueDate,
        closing_date: contract.closingDate,
        seller_bank_details: contract.sellerBankDetails, // Salva o snapshot da conta
        status: contract.status,
        signature_data: contract.signatureData
    };

    const isNew = contract.id.length < 15;

    // Helper para realizar a operação (Insert ou Update)
    const performSave = async (payload: any) => {
        if (isNew) {
            return await supabase.from('contracts').insert(payload);
        } else {
            return await supabase.from('contracts').update(payload).eq('id', contract.id);
        }
    };

    // Tenta salvar
    let { error } = await performSave(dbContract);

    // Lógica de Fallback: Se o erro for de coluna inexistente (código 42703 no Postgres), 
    // removemos o campo problemático e tentamos novamente.
    if (error && (error.code === '42703' || error.message?.includes('seller_bank_details'))) {
        console.warn("DMS Warning: Coluna 'seller_bank_details' não encontrada no banco. Salvando em modo de compatibilidade (sem dados bancários snapshot).");

        // Remove a propriedade problemática
        delete (dbContract as any).seller_bank_details;

        // Tenta novamente
        const retry = await performSave(dbContract);
        error = retry.error;
    }

    if (error) {
        throw new Error(error.message);
    }
};

