export const saveContract = async (contract: Contract) => {
    const dbContract = {
        number: contract.number,
        product: contract.product,
        crop: contract.crop,
        seller_name: contract.sellerName,
        seller_doc: contract.sellerDoc,
        buyer_name: contract.buyerName,
        buyer_doc: contract.buyerDoc,
        total_bags: contract.totalBags,
        total_tons: contract.totalTons,
        delivered_bags: contract.deliveredBags,
        freight_type: contract.freightType,
        pickup_location: contract.pickupLocation,
        shipment_start_date: contract.shipmentStartDate,
        shipment_end_date: contract.shipmentEndDate,
        observation: contract.observation,
        currency: contract.currency,
        exchange_rate: contract.exchangeRate,
        pricing_mode: contract.pricingMode,
        is_fixed: contract.isFixed,
        base_price: contract.basePrice,
        cbot_component: contract.cbotComponent,
        basis_component: contract.basisComponent,
        cost_component: contract.costComponent,
        final_price: contract.finalPrice,
        commission_per_bag: contract.commissionPerBag,
        payment_date: contract.paymentDate,
        commission_due_date: contract.commissionDueDate,
        closing_date: contract.closingDate,
        seller_bank_details: contract.sellerBankDetails, // Salva o snapshot da conta
        status: contract.status,
        signature_data: contract.signatureData
    };

    const isNew = contract.id.length < 15;

    // Helper para realizar a operação (Insert ou Update)
    const performSave = async (payload: any) => {
        if (isNew) {
            return await supabase.from('contracts').insert(payload);
        } else {
            return await supabase.from('contracts').update(payload).eq('id', contract.id);
        }
    };

    // Tenta salvar
    let { error } = await performSave(dbContract);

    // Lógica de Fallback: Se o erro for de coluna inexistente (código 42703 no Postgres), 
    // removemos o campo problemático e tentamos novamente.
    if (error && (error.code === '42703' || error.message?.includes('seller_bank_details'))) {
        console.warn("DMS Warning: Coluna 'seller_bank_details' não encontrada no banco. Salvando em modo de compatibilidade (sem dados bancários snapshot).");

        // Remove a propriedade problemática
        delete (dbContract as any).seller_bank_details;

        // Tenta novamente
        const retry = await performSave(dbContract);
        error = retry.error;
    }

    if (error) {
        throw new Error(error.message);
    }
};

export const addShipment = async (shipment: Shipment) => {
    const dbShipment = {
        contract_id: shipment.contractId,
        plate: shipment.plate,
        ticket_number: shipment.ticketNumber,
        weight_kg: shipment.weightKg,
        bags_count: shipment.bagsCount,
        date: shipment.date
    };

    const { error } = await supabase.from('shipments').insert(dbShipment);
    if (error) throw error;

    const { data: contract } = await supabase.from('contracts').select('delivered_bags').eq('id', shipment.contractId).single();
    if (contract) {
        const newTotal = (Number(contract.delivered_bags) || 0) + shipment.bagsCount;
        await supabase.from('contracts').update({ delivered_bags: newTotal }).eq('id', shipment.contractId);
    }
};

export const generateContractNumber = async (product: string, crop: string): Promise<string> => {
  const letter = product === 'SOJA' ? 'S' : product === 'MILHO' ? 'M' : 'T';
  const cleanCrop = crop.trim();
  let yearSuffix = '00';

  if (cleanCrop.includes('/')) {
    yearSuffix = cleanCrop.split('/')[1]; 
  } else if (cleanCrop.length >= 2) {
    yearSuffix = cleanCrop.slice(-2); 
  }

  // BUSCA O ÚLTIMO NÚMERO USADO PARA CALCULAR O PRÓXIMO (Evita duplicidade por deleção)
  // Ao invés de contar, pegamos todos os números e achamos o maior sequencial.
  const { data, error } = await supabase
    .from('contracts')
    .select('number')
    .eq('product', product)
    .eq('crop', crop);

  if (error) {
      console.error('Erro ao gerar número de contrato:', error);
  }

  // COMEÇAR DE 2000 (para gerar 2001)
  let maxSeq = 2000;

  if (data && data.length > 0) {
      data.forEach(row => {
          if (row.number) {
              // Extrai os dígitos do início da string (Ex: 1001 de 1001S24)
              const match = row.number.match(/^(\d+)/);
              if (match) {
                  const seq = parseInt(match[1], 10);
                  if (!isNaN(seq) && seq > maxSeq) {
                      maxSeq = seq;
                  }
              }
          }
      });
  }

  const nextSeq = maxSeq + 1;

  return `${nextSeq}${letter}${yearSuffix}`;
};

// --- BULK OPERATIONS FOR CSV IMPORT ---

// Generic Insert (Modified to UPSERT with DEDUPLICATION and SCHEMA MAPPING)
export const bulkInsert = async (table: string, data: any[]) => {
    // 1. Identificar chave de conflito (Unique Key)
    let conflictKey = '';
    if (table === 'contracts') conflictKey = 'number';
    if (table === 'buyers') conflictKey = 'doc';

    let dataToInsert = data;

    // FIX SCHEMA: Remove closing_date if exists in CSV to prevent error
    if (table === 'contracts') {
        dataToInsert = dataToInsert.map(item => {
            const { closing_date, ...rest } = item;
            // Map closing_date to created_at if created_at is not provided, preserving the business date
            if (closing_date && !rest.created_at) {
                rest.created_at = closing_date;
            }

            // --- ARREDONDAMENTOS ---
            // Sacas (2 casas)
            let totalBags = parseFloat(item.total_bags);
            if (!isNaN(totalBags)) totalBags = parseFloat(totalBags.toFixed(2));

            // Toneladas (2 casas)
            let totalTons = parseFloat(item.total_tons);
            if (!isNaN(totalTons)) totalTons = parseFloat(totalTons.toFixed(2));

            // Preço Final (2 casas)
            let finalPrice = parseFloat(item.final_price);
            const isFixed = !isNaN(finalPrice) && finalPrice > 0;
            if (isFixed) finalPrice = parseFloat(finalPrice.toFixed(2));

            return {
                ...rest,
                total_bags: totalBags,
                total_tons: totalTons,
                final_price: finalPrice,
                closing_date, // Garante que vai para a coluna correta
                is_fixed: isFixed // Define status de fixação automaticamente
            };
        });
    }

    // 2. Se houver chave, deduplicar o array ANTES de enviar para o banco
    if (conflictKey) {
        const uniqueMap = new Map();
        dataToInsert.forEach(item => {
            const key = item[conflictKey];
            if (key) {
                // Se já existir, sobrescreve com o último encontrado
                uniqueMap.set(key, item);
            }
        });
        dataToInsert = Array.from(uniqueMap.values());
    }

    // 3. Executar UPSERT com os dados limpos
    const options = conflictKey ? { onConflict: conflictKey } : {};

    const { error } = await supabase.from(table).upsert(dataToInsert, options);
    if (error) throw error;
};

// Specialized Producer Insert (Handles Bank Details JSON + Deduplication + UPSERT)
export const bulkInsertProducers = async (data: any[]) => {
    const normalize = (str: string) => str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase();

    const formattedData = data.map(row => {
        const fTypeRaw = row.funrural_type ? normalize(row.funrural_type.toString()) : '';
        let fType = null;

        if (fTypeRaw.includes('FOLHA')) fType = 'FOLHA';
        else if (fTypeRaw.includes('PJ') || fTypeRaw.includes('ISENTO')) fType = 'PJ_ISENTO';
        else if (fTypeRaw.includes('COMERCIALIZA')) fType = 'COMERCIALIZACAO';

        return {
            name: row.name,
            doc: row.doc,
            state_insc: row.state_insc,
            email: row.email,
            region: row.region,
            funrural_type: fType,
            // Importação assume 1 conta por linha, cria array
            bank_details: [{
                bankName: row.bank_name || '',
                agency: row.agency || '',
                account: row.account || '',
                holder: row.holder || row.name,
                holderDoc: row.holder_doc || row.doc
            }]
        };
    });

    const uniqueMap = new Map();
    formattedData.forEach(item => {
        if (item.doc) {
            uniqueMap.set(item.doc, item);
        }
    });
    const uniqueProducers = Array.from(uniqueMap.values());

    const { error } = await supabase.from('producers').upsert(uniqueProducers, { onConflict: 'doc' });
    if (error) throw error;
};

// Specialized Farm Insert (Links to Producer by Doc)
export const bulkInsertFarms = async (csvData: any[]) => {
    if (csvData.length === 0) return;

    const documents = [...new Set(csvData.map(row => row.producer_doc).filter(Boolean))];

    const { data: producers, error } = await supabase
        .from('producers')
        .select('id, doc')
        .in('doc', documents);

    if (error) throw new Error('Erro ao buscar produtores: ' + error.message);
    if (!producers) return;

    const docMap = new Map();
    producers.forEach(p => docMap.set(p.doc, p.id));

    const farmsToInsert: any[] = [];
    const errors: string[] = [];

    const uniqueFarmCheck = new Set();

    csvData.forEach(row => {
        const producerId = docMap.get(row.producer_doc);
        if (producerId) {
            const key = `${producerId}-${row.name}`;
            if (!uniqueFarmCheck.has(key)) {
                uniqueFarmCheck.add(key);
                farmsToInsert.push({
                    producer_id: producerId,
                    name: row.name,
                    address: row.address
                });
            }
        } else {
            errors.push(`Produtor com CPF/CNPJ ${row.producer_doc} não encontrado.`);
        }
    });

    if (farmsToInsert.length > 0) {
        const { error: insertError } = await supabase.from('farms').upsert(farmsToInsert, { ignoreDuplicates: true });
        if (insertError) throw insertError;
    }

    if (errors.length > 0) {
        console.warn("Algumas fazendas não foram importadas:", errors);
        throw new Error(`Importação parcial. ${farmsToInsert.length} salvas. ${errors.length} falharam (Produtor não encontrado).`);
    }
};

