    const normalize = (str: string) => str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase();

    const formattedData = data.map(row => {
        const fTypeRaw = row.funrural_type ? normalize(row.funrural_type.toString()) : '';
        let fType = null;

        if (fTypeRaw.includes('FOLHA')) fType = 'FOLHA';
        else if (fTypeRaw.includes('PJ') || fTypeRaw.includes('ISENTO')) fType = 'PJ_ISENTO';
        else if (fTypeRaw.includes('COMERCIALIZA')) fType = 'COMERCIALIZACAO';

        return {
            name: row.name,
            doc: row.doc,
            state_insc: row.state_insc,
            email: row.email,
            region: row.region,
            funrural_type: fType,
            // Importação assume 1 conta por linha, cria array
            bank_details: [{
                bankName: row.bank_name || '',
                agency: row.agency || '',
                account: row.account || '',
                holder: row.holder || row.name,
                holderDoc: row.holder_doc || row.doc
            }]
        };
    });

    const uniqueMap = new Map();
    formattedData.forEach(item => {
        if (item.doc) {
            uniqueMap.set(item.doc, item);
        }
    });
    const uniqueProducers = Array.from(uniqueMap.values());

    const { error } = await supabase.from('producers').upsert(uniqueProducers, { onConflict: 'doc' });
    if (error) throw error;
};

// Specialized Farm Insert (Links to Producer by Doc)
export const bulkInsertFarms = async (csvData: any[]) => {
    if (csvData.length === 0) return;

    const documents = [...new Set(csvData.map(row => row.producer_doc).filter(Boolean))];

    const { data: producers, error } = await supabase
        .from('producers')
        .select('id, doc')
        .in('doc', documents);

    if (error) throw new Error('Erro ao buscar produtores: ' + error.message);
    if (!producers) return;

    const docMap = new Map();
    producers.forEach(p => docMap.set(p.doc, p.id));

    const farmsToInsert: any[] = [];
    const errors: string[] = [];

    const uniqueFarmCheck = new Set();

    csvData.forEach(row => {
        const producerId = docMap.get(row.producer_doc);
        if (producerId) {
            const key = `${producerId}-${row.name}`;
            if (!uniqueFarmCheck.has(key)) {
                uniqueFarmCheck.add(key);
                farmsToInsert.push({
                    producer_id: producerId,
                    name: row.name,
                    address: row.address
                });
            }
        } else {
            errors.push(`Produtor com CPF/CNPJ ${row.producer_doc} não encontrado.`);
        }
    });

    if (farmsToInsert.length > 0) {
        const { error: insertError } = await supabase.from('farms').upsert(farmsToInsert, { ignoreDuplicates: true });
        if (insertError) throw insertError;
    }

    if (errors.length > 0) {
        console.warn("Algumas fazendas não foram importadas:", errors);
        throw new Error(`Importação parcial. ${farmsToInsert.length} salvas. ${errors.length} falharam (Produtor não encontrado).`);
    }
};

import { supabase } from './supabase';
import { Contract, Shipment, ContractStatus, PricingMode, MarketData, Producer, Buyer, Farm, BankAccount } from '../types';

// --- MAPPING HELPERS ---
// Converte do Banco (snake_case) para App (camelCase)
const mapProducerFromDB = (p: any): Producer => {
    // Garante que bankDetails seja sempre um array, mesmo se vier como objeto único (legado)
    let banks: BankAccount[] = [];
    if (Array.isArray(p.bank_details)) {
        banks = p.bank_details;
    } else if (p.bank_details && typeof p.bank_details === 'object') {
        banks = [p.bank_details];
    }

    return {
        id: p.id,
        name: p.name,
        doc: p.doc,
        stateInsc: p.state_insc,
        email: p.email,
        region: p.region,
        funruralType: p.funrural_type,
        bankDetails: banks,
        farms: p.farms ? p.farms.map((f: any) => ({
            id: f.id,
            name: f.name,
            address: f.address
        })) : []
    };
};

const mapBuyerFromDB = (b: any): Buyer => ({
    id: b.id,
    name: b.name,
    doc: b.doc,
    stateInsc: b.state_insc,
    address: b.address,
    type: b.type
});

const mapContractFromDB = (c: any): Contract => {
    // Helper para garantir parse correto da conta bancária
    let bankDetails: BankAccount | undefined = undefined;
    if (c.seller_bank_details) {
        if (typeof c.seller_bank_details === 'string') {
            try {
                bankDetails = JSON.parse(c.seller_bank_details);
            } catch (e) {
                console.error("Erro ao parsear conta bancária do contrato", c.number);
            }
        } else {
            bankDetails = c.seller_bank_details;
        }
    }

    return {
        id: c.id,
        number: c.number,
        product: c.product,
        crop: c.crop,
        sellerName: c.seller_name,
        sellerDoc: c.seller_doc, 
        buyerName: c.buyer_name,
        buyerDoc: c.buyer_doc, 
        totalBags: c.total_bags,
        totalTons: c.total_tons,
        deliveredBags: c.delivered_bags,
        freightType: c.freight_type,
        pickupLocation: c.pickup_location,
        shipmentStartDate: c.shipment_start_date,
        shipmentEndDate: c.shipment_end_date,
        observation: c.observation,
        currency: c.currency,
        exchangeRate: c.exchange_rate,
        pricingMode: c.pricing_mode,
        isFixed: c.is_fixed,
        basePrice: c.base_price,
        cbotComponent: c.cbot_component,
        basisComponent: c.basis_component,
        costComponent: c.cost_component,
        finalPrice: c.final_price,
        commissionPerBag: c.commission_per_bag,
        paymentDate: c.payment_date,
        commissionDueDate: c.commission_due_date,
        closingDate: c.closing_date,
        sellerBankDetails: bankDetails, // Usa o valor processado
        status: c.status,
        createdAt: c.created_at,
        signatureData: c.signature_data
    };
};

const mapShipmentFromDB = (s: any): Shipment => ({
    id: s.id,
